f=$(find /app/data -name '*.nwb' | sort | head -1); python - "$f" > /tmp/schema.txt <<'PY'
import sys
from pynwb import NWBHDF5IO
with NWBHDF5IO(sys.argv[1],'r',load_namespaces=True) as io:
 n=io.read()
 print('FILE',sys.argv[1]); print('SUBJECT',n.subject.subject_id,'SESSION',n.session_id)
 print('NTRIAL',len(n.trials)); print('TRIAL_COLS',list(n.trials.colnames))
 for c in n.trials.colnames:
  try: print(' T',c,repr(n.trials[c][:5]))
  except Exception as e: print(' T',c,type(e).__name__)
 print('NUNITS',len(n.units)); print('UNIT_COLS',list(n.units.colnames))
 for c in n.units.colnames:
  if c!='spike_times':
   try: print(' U',c,repr(n.units[c][:5]))
   except Exception as e: print(' U',c,type(e).__name__)
 print('ACQ',list(n.acquisition)); print('STIM',list(n.stimulus)); print('PROC',list(n.processing)); print('INTERVALS',list(n.intervals))
 for mn,m in n.processing.items():
  print('MODULE',mn,list(m.data_interfaces))
  for k,v in m.data_interfaces.items(): print(' I',k,type(v).__name__)
PY
cat /tmp/schema.txt

f=$(find /app/data -name '*.nwb' | sort | head -1); python - "$f" <<'PY'
import sys,numpy as np
from pynwb import NWBHDF5IO
with NWBHDF5IO(sys.argv[1],'r',load_namespaces=True) as io:
 n=io.read(); print('FILE',sys.argv[1]); print('SUBJECT',n.subject.subject_id,'SESSION',n.session_id)
 print('TRIALS',len(n.trials),list(n.trials.colnames))
 for c in n.trials.colnames:
  a=n.trials[c][:]
  if np.asarray(a).dtype!=object: print(' T',c,'shape',np.shape(a),'dtype',np.asarray(a).dtype,'first',np.asarray(a)[:5],'unique',np.unique(a)[:15])
  else: print(' T',c,'shape',np.shape(a),'first',[str(x)[:80] for x in a[:5]])
 print('UNITS',len(n.units),list(n.units.colnames))
 for c in n.units.colnames:
  if c in ('spike_times','waveform_mean','waveform_sd'): continue
  a=n.units[c][:]; ar=np.asarray(a)
  if ar.ndim==1: print(' U',c,'dtype',ar.dtype,'first',ar[:5],'unique',np.unique(ar)[:20] if ar.dtype!=object else list(dict.fromkeys(map(str,ar)))[:20])
  else: print(' U',c,'shape',ar.shape)
 for an,obj in n.acquisition.items():
  print('ACQ',an,type(obj).__name__)
  members=getattr(obj,'time_series',{})
  for k,v in members.items():
   d=v.data; ts=v.timestamps
   print(' TS',k,type(v).__name__,'data_shape',getattr(d,'shape',None),'dtype',getattr(d,'dtype',None),'timestamps_shape',getattr(ts,'shape',None),'rate',v.rate,'start',v.starting_time,'unit',v.unit)
   try: print('   data_first',np.asarray(d[:5]).reshape(-1)[:10])
   except: pass
   try: print('   ts_first',np.asarray(ts[:5]))
   except: pass
PY
